from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> (borrower, borrow_date) or None if available
        self.user_books = {}  # user -> set of borrowed book_ids
        self.user_fines = {}  # user -> total unpaid fines

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None
        # Initialize user records if needed
        if book_id not in self.books:
            self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already has a book
        if user in self.user_fines and self.user_fines[user] > 0:
            if user in self.user_books and len(self.user_books[user]) >= 1:
                raise ValueError(f"User {user} has unpaid fines and already has a book")

        # Record the borrowing
        self.books[book_id] = (user, day)

        if user not in self.user_books:
            self.user_books[user] = set()
        self.user_books[user].add(book_id)

        # Initialize fine record for user if not exists
        if user not in self.user_fines:
            self.user_fines[user] = 0.0

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is None:
            raise ValueError(f"Book {book_id} is not borrowed")

        borrower, borrow_date = self.books[book_id]
        if borrower != user:
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Calculate fine
        due_date = borrow_date + timedelta(days=self.loan_days)
        fine = 0.0

        if day > due_date:
            # Count only weekdays (Mon-Fri) as delay days
            delay_days = 0
            current = due_date + timedelta(days=1)
            while current <= day:
                # Monday=0, Sunday=6, so 5 and 6 are weekend
                if current.weekday() < 5:  # Monday to Friday
                    delay_days += 1
                current += timedelta(days=1)

            fine = delay_days * self.daily_fine

        # Update records
        self.books[book_id] = None
        if user in self.user_books and book_id in self.user_books[user]:
            self.user_books[user].remove(book_id)
            if len(self.user_books[user]) == 0:
                del self.user_books[user]

        # Add to user's unpaid fines
        if user not in self.user_fines:
            self.user_fines[user] = 0.0
        self.user_fines[user] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.user_fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.user_fines:
            self.user_fines[user] = 0.0
